//go:build linux

package platform

import (
	"errors"
	"fmt"
	"os"
	"path/filepath"
)

// nautilusScript returns the body of a Nautilus script that invokes gosvn with
// the first selected file path (or the current directory when none selected).
func nautilusScript(arg string) string {
	bin := Executable()
	if bin == "" {
		bin = "gosvn"
	}
	return fmt.Sprintf(`#!/bin/sh
# Auto-generated by GoSVN. Do not edit.
path=$(printf '%%s' "$NAUTILUS_SCRIPT_SELECTED_FILE_PATHS" | head -n 1)
if [ -z "$path" ]; then
    path="$PWD"
fi
exec %s %s "$path"
`, Quote(bin), arg)
}

func nautilusScriptsDir() (string, error) {
	home, err := os.UserHomeDir()
	if err != nil {
		return "", err
	}
	return filepath.Join(home, ".local", "share", "nautilus", "scripts"), nil
}

// InstallIntegration installs GoSVN launchers into the current user's Nautilus
// scripts directory so they appear in the right-click "Scripts" menu.
func InstallIntegration() error {
	dir, err := nautilusScriptsDir()
	if err != nil {
		return err
	}
	if err := os.MkdirAll(dir, 0o755); err != nil {
		return err
	}
	scripts := map[string]string{
		"GoSVN-Commit": "commit",
		"GoSVN-Update": "update",
		"GoSVN-Log":    "log",
		"GoSVN-Diff":   "diff",
	}
	for name, arg := range scripts {
		p := filepath.Join(dir, name)
		if err := os.WriteFile(p, []byte(nautilusScript(arg)), 0o755); err != nil {
			return err
		}
	}
	return nil
}

// UninstallIntegration removes the GoSVN Nautilus scripts installed by
// InstallIntegration.
func UninstallIntegration() error {
	dir, err := nautilusScriptsDir()
	if err != nil {
		return err
	}
	var firstErr error
	for _, name := range []string{"GoSVN-Commit", "GoSVN-Update", "GoSVN-Log", "GoSVN-Diff"} {
		p := filepath.Join(dir, name)
		if err := os.Remove(p); err != nil && !errors.Is(err, os.ErrNotExist) {
			if firstErr == nil {
				firstErr = err
			}
		}
	}
	return firstErr
}
